299	        if (!current(phase) || expectedRevision !== authoritative.revision)
300	          return { status: 'REFUSED', message: 'Stale intent/CAS refused' }
301	        let renameAttempted = false
302	        let outcome: SettingsOutcome
303	        // Before OS rename, refusal can prove no durable write. After it, reconcile ownership.
304	        try {
305	          const base = await readAuthoritative()
306	          if (!current(phase) || base.revision !== expectedRevision)
307	            outcome = { status: 'REFUSED', message: 'Authoritative CAS refused' }
308	          else {
309	            const durable = await write(phase, choice, base, () => {
310	              renameAttempted = true
311	            })
312	            outcome = { status: 'ACK', durable }
313	          }
314	        } catch (error) {
315	          outcome = { status: renameAttempted ? 'UNKNOWN' : 'REFUSED', message: errorText(error) }
316	        }
317	        try {
318	          await files.remove(staged)
319	        } catch (error) {
